import type { AutocompleteInteraction, PermissionResolvable } from "discord.js";
import type { CommandContext } from "../context";
import type { CommandHandlerConfig } from "./command";
import type { CommandRoute } from "./route";

/**
 * Effective access restrictions inherited by a command route.
 *
 * @internal
 */
export interface EffectiveCommandAccess {
	devOnly: boolean;
	guildOnly: boolean;
	userPermissions: readonly PermissionResolvable[];
	botPermissions: readonly PermissionResolvable[];
}

/**
 * Computes the cumulative group and command access settings for a route.
 *
 * @internal
 */
export function getEffectiveCommandAccess(
	route: CommandRoute,
): EffectiveCommandAccess {
	const groups = route.groups ?? [];

	return {
		devOnly:
			route.command.devOnly === true ||
			groups.some((group) => group.devOnly === true),

		guildOnly:
			route.command.guildOnly === true ||
			groups.some((group) => group.guildOnly === true),

		userPermissions: [
			...groups.flatMap((group) => group.userPermissions ?? []),
			...(route.command.userPermissions ?? []),
		],

		botPermissions: [
			...groups.flatMap((group) => group.botPermissions ?? []),
			...(route.command.botPermissions ?? []),
		],
	};
}

/**
 * Returns whether a route is enabled for slash-command registration.
 *
 * A route is disabled when either its command or one of its parent groups has
 * `slash` set to `false`.
 *
 * @internal
 */
export function isSlashRouteEnabled(route: CommandRoute): boolean {
	return (
		route.command.slash !== false &&
		(route.groups ?? []).every((group) => group.slash !== false)
	);
}

type AccessControllerConfig = Required<
	Pick<CommandHandlerConfig, "allowBots" | "allowOnlyDevs" | "devIds">
> & {
	isIgnored?: CommandHandlerConfig["isIgnored"];
};

/**
 * Applies global user filtering and route-specific access checks.
 *
 * @internal
 */
export class CommandAccessController {
	public constructor(private readonly config: AccessControllerConfig) {}

	private isDeveloper(userId: string): boolean {
		return this.config.devIds.includes(userId);
	}

	/**
	 * Returns whether a user is globally eligible for command processing.
	 *
	 * This check covers bot users, ignored users, and global developer-only
	 * mode. Rejected users are ignored silently.
	 */
	public canProcessUser(userId: string, isBot: boolean): boolean {
		if (isBot && !this.config.allowBots) {
			return false;
		}

		if (this.config.isIgnored?.(userId)) {
			return false;
		}

		if (this.config.allowOnlyDevs && !this.isDeveloper(userId)) {
			return false;
		}

		return true;
	}

	/**
	 * Verifies inherited developer restrictions, guild restrictions, and
	 * channel permissions for a route.
	 *
	 * Developer-only failures are ignored silently, matching global
	 * developer-only mode. Other access failures are rendered through the
	 * supplied command context.
	 *
	 * @param route - Route being invoked.
	 * @param context - Context used to inspect the invocation and send errors.
	 */
	public async checkRoute(
		route: CommandRoute,
		context: CommandContext<Record<string, never>>,
	): Promise<boolean> {
		const access = getEffectiveCommandAccess(route);

		if (access.devOnly && !this.isDeveloper(context.userId)) {
			return false;
		}

		if (access.guildOnly && !context.guildOrNull) {
			await context.replyError("This command can only be used in a server.");

			return false;
		}

		const guild = context.guildOrNull;

		if (!guild) {
			return true;
		}

		const channel = context.raw.channel;

		if (!channel?.isTextBased() || channel.isDMBased()) {
			return true;
		}

		const member = context.member ?? (await context.fetchMember());

		if (!member) {
			await context.replyError("Could not resolve your server member data.");

			return false;
		}

		if (access.userPermissions.length > 0) {
			const missingPermissions = member
				.permissionsIn(channel)
				.missing(access.userPermissions);

			if (missingPermissions.length > 0) {
				await context.replyError(
					"You lack the required permissions to use this: " +
						`\`${missingPermissions.join(", ")}\``,
				);

				return false;
			}
		}

		if (access.botPermissions.length > 0) {
			const botMember =
				guild.members.me ?? (await guild.members.fetchMe().catch(() => null));

			if (!botMember) {
				await context.replyError("Could not resolve my server member data.");

				return false;
			}

			const missingPermissions = botMember
				.permissionsIn(channel)
				.missing(access.botPermissions);

			if (missingPermissions.length > 0) {
				await context.replyError(
					"I am missing permissions to execute this: " +
						`\`${missingPermissions.join(", ")}\``,
				);

				return false;
			}
		}

		return true;
	}

	public checkAutocompleteRoute(
		route: CommandRoute,
		interaction: AutocompleteInteraction,
	): boolean {
		const access = getEffectiveCommandAccess(route);

		if (access.devOnly && !this.isDeveloper(interaction.user.id)) {
			return false;
		}

		if (access.guildOnly && !interaction.inGuild()) {
			return false;
		}

		if (!interaction.inGuild()) {
			return true;
		}

		if (
			access.userPermissions.length > 0 &&
			(!interaction.memberPermissions ||
				interaction.memberPermissions.missing(access.userPermissions).length >
					0)
		) {
			return false;
		}

		if (
			access.botPermissions.length > 0 &&
			(!interaction.appPermissions ||
				interaction.appPermissions.missing(access.botPermissions).length > 0)
		) {
			return false;
		}

		return true;
	}
}

import type { Message, PermissionResolvable } from "discord.js";
import type { ArgumentSchema, ParsedArguments } from "../arguments";
import type {
    CommandContext,
    CommandFeedbackRenderer,
    CommandLogger,
} from "../context";
import type { HelpCommandConfig } from "../help/types";

/** @internal Empty schema used by commands that declare no arguments. */
export const EMPTY_ARGUMENTS = {} as const satisfies ArgumentSchema;

/**
 * Describes a command before it is assigned to a concrete route.
 *
 * Directory-loaded commands may omit `name`; the command loader derives the
 * name from the module filename. Commands registered directly through
 * `CommandManager.registerCommands()` must include a name.
 *
 * @typeParam Schema - Argument schema used to infer `ctx.args`.
 */
export interface CommandDefinition<
    Schema extends ArgumentSchema = typeof EMPTY_ARGUMENTS,
> {
    /**
     * Canonical lowercase command name.
     *
     * Names must contain 1–32 lowercase letters, numbers, hyphens, or
     * underscores. This may be omitted only for directory-loaded commands.
     */
    name?: string;

    /**
     * Human-readable command description.
     *
     * Discord requires descriptions to contain between 1 and 100 characters.
     */
    description: string;

    /**
     * Alternative names accepted by prefix commands.
     *
     * Aliases do not create additional slash-command names.
     */
    aliases?: readonly string[];

    /**
     * Strongly typed argument schema shared by prefix and slash commands.
     *
     * Parsed values are exposed through `ctx.args`.
     */
    arguments?: Schema;

    /**
     * Whether this command is registered as a slash command.
     *
     * Prefix-command availability is unaffected.
     *
     * @defaultValue true
     */
    slash?: boolean;

    /**
     * Whether the command may only be executed inside a guild.
     *
     * When enabled, attempts to use the command in a DM receive an error
     * response.
     */
    guildOnly?: boolean;

    /**
     * Restricts this command to users listed in the command manager's
     * `devIds` configuration.
     *
     * This restriction is also inherited from parent command groups.
     *
     * @defaultValue false
     */
    devOnly?: boolean;

    /**
     * Executes this command when its parent route is invoked without an explicit
     * subcommand in a prefix message.
     *
     * This has no effect on slash commands.
     *
     * @defaultValue false
     */
    messageDefault?: boolean;

    /**
     * Permissions the invoking guild member must have in the current channel.
     */
    userPermissions?: readonly PermissionResolvable[];

    /**
     * Permissions the bot must have in the current channel.
     */
    botPermissions?: readonly PermissionResolvable[];

    /**
     * Executes the command with validated and strongly typed arguments.
     *
     * Errors thrown from this function are logged, reported to the user, and
     * emitted through the manager's `commandError` lifecycle event.
     */
    execute(ctx: CommandContext<ParsedArguments<Schema>>): Promise<void> | void;
}

/**
 * A command with a concrete canonical name.
 *
 * This is the form accepted by direct registration and stored by the command
 * manager after directory resolution.
 */
export type Command<Schema extends ArgumentSchema = typeof EMPTY_ARGUMENTS> =
    CommandDefinition<Schema> & {
        name: string;
    };

/**
 * A command whose specific argument schema is not statically known.
 *
 * Framework internals use this type after command definitions have been
 * collected into a heterogeneous registry.
 */
export type AnyCommand = Command<ArgumentSchema>;

/**
 * A command definition whose specific argument schema is not statically known.
 */
export type AnyCommandDefinition = CommandDefinition<ArgumentSchema>;

/**
 * Defines a command while preserving literal argument-schema inference.
 *
 * This function does not register or modify the command. It exists to preserve
 * the exact schema type so that `ctx.args` is inferred automatically.
 *
 * @example
 * ```ts
 * const command = defineCommand({
 *     name: "greet",
 *     description: "Greets a user.",
 *     arguments: {
 *         user: argument.user({
 *             description: "The user to greet.",
 *             required: true,
 *         }),
 *     },
 *     execute(ctx) {
 *         ctx.args.user;
 *     },
 * });
 * ```
 */
export function defineCommand<
    const Schema extends ArgumentSchema = typeof EMPTY_ARGUMENTS,
>(command: Command<Schema>): Command<Schema>;

/**
 * Defines a directory-loaded command whose name may be derived from its
 * filename.
 */
export function defineCommand<
    const Schema extends ArgumentSchema = typeof EMPTY_ARGUMENTS,
>(command: CommandDefinition<Schema>): CommandDefinition<Schema>;

export function defineCommand<
    const Schema extends ArgumentSchema = typeof EMPTY_ARGUMENTS,
>(command: CommandDefinition<Schema>): CommandDefinition<Schema> {
    return command;
}

/**
 * Metadata inherited by commands beneath a command directory.
 *
 * Group settings are cumulative. Nested commands inherit guild restrictions,
 * developer restrictions, and permission requirements from every parent group.
 */
export interface CommandGroup {
    /**
     * Description used for the root slash command or slash subcommand group.
     */
    description: string;

    /**
     * Alternative path-segment names accepted by prefix commands.
     *
     * Group aliases do not affect slash-command paths.
     */
    aliases?: readonly string[];

    /**
     * Disables slash registration for all routes beneath this group.
     *
     * Prefix commands remain available.
     *
     * @defaultValue true
     */
    slash?: boolean;

    /**
     * Restricts every route beneath this group to guilds.
     */
    guildOnly?: boolean;

    /**
     * Restricts every route beneath this group to users listed in the command
     * manager's `devIds` configuration.
     *
     * Nested groups and commands cannot remove this restriction.
     *
     * @defaultValue false
     */
    devOnly?: boolean;

    /**
     * User permissions inherited by routes beneath this group.
     */
    userPermissions?: readonly PermissionResolvable[];

    /**
     * Bot permissions inherited by routes beneath this group.
     */
    botPermissions?: readonly PermissionResolvable[];
}

/**
 * Defines command-group metadata while preserving its inferred type.
 *
 * This function does not register or modify the group.
 */
export function defineCommandGroup(group: CommandGroup): CommandGroup {
    return group;
}

/**
 * Configuration used when constructing a `CommandManager`.
 */
export interface CommandHandlerConfig {
    /**
     * Prefix used for message commands.
     *
     * A resolver may return a different prefix for each message, guild, or
     * channel. Both synchronous and asynchronous resolvers are supported.
     */
    prefix: string | ((message: Message) => string | Promise<string>);

    /**
     * Restricts all command execution to users listed in `devIds`.
     *
     * @defaultValue false
     */
    allowOnlyDevs?: boolean;

    /**
     * User IDs recognized as bot developers.
     *
     * These IDs are used by the global `allowOnlyDevs` option and by commands
     * or groups whose `devOnly` option is enabled.
     *
     * @defaultValue []
     */
    devIds?: readonly string[];

    /**
     * Logger used for execution failures and responder warnings.
     *
     * The framework's console-based logger is used by default.
     */
    logger?: CommandLogger;

    /**
     * Renderer used by `ctx.replyError()` and `ctx.replySuccess()`.
     *
     * The default renderer produces Discord Components V2 responses.
     */
    feedbackRenderer?: CommandFeedbackRenderer;

    /**
     * Returns `true` when a user should be ignored silently.
     *
     * Ignored users do not receive an error response.
     */
    isIgnored?: (userId: string) => boolean;

    /**
     * Whether bot-authored messages and interactions may invoke commands.
     *
     * @defaultValue false
     */
    allowBots?: boolean;

    /**
     * Controls Voxa's generated help command.
     *
     * Pass `false` to disable it, `true` to use defaults, or an options
     * object to customize its name, presentation, and behavior.
     *
     * @defaultValue true
     */
    help?: HelpCommandConfig;
}

import { EventEmitter } from "node:events";
import type {
    AutocompleteInteraction,
    BaseInteraction,
    ChatInputCommandInteraction,
    Collection,
    Message,
} from "discord.js";
import {
    type ArgumentSchema,
    formatArgumentUsage,
    type ParsedArguments,
    parseInteractionArguments,
    parseMessageArguments,
    respondToArgumentAutocomplete,
    tokenizeArguments,
} from "../arguments";
import {
    CommandContext,
    defaultCommandFeedbackRenderer,
    defaultCommandLogger,
} from "../context";
import {
    createGeneratedHelpRoute,
    type ResolvedHelpCommandOptions,
    resolveHelpCommandOptions,
} from "../help";
import { CommandAccessController, isSlashRouteEnabled } from "./access";
import {
    type AnyCommand,
    type CommandHandlerConfig,
    EMPTY_ARGUMENTS,
} from "./command";
import { type CommandRoute, CommandRouteRegistry } from "./route";

type ResolvedCommandHandlerConfig = Required<
    Omit<CommandHandlerConfig, "help" | "isIgnored">
> & {
    help: ResolvedHelpCommandOptions | null;
    isIgnored?: CommandHandlerConfig["isIgnored"];
};

function resolveCommandHandlerConfig(
    config: CommandHandlerConfig,
): ResolvedCommandHandlerConfig {
    return {
        prefix: config.prefix,
        allowOnlyDevs: config.allowOnlyDevs ?? false,
        devIds: config.devIds ?? [],
        logger: config.logger ?? defaultCommandLogger,
        feedbackRenderer:
            config.feedbackRenderer ?? defaultCommandFeedbackRenderer,
        isIgnored: config.isIgnored,
        allowBots: config.allowBots ?? false,
        help: resolveHelpCommandOptions(config.help),
    };
}

/**
 * Lifecycle events emitted by {@link CommandManager}.
 *
 * This interface documents the argument order for each event. The manager
 * continues to extend Node.js `EventEmitter`, so listeners are attached with
 * `manager.on(eventName, listener)`.
 */
export interface CommandManagerEventMap {
    /**
     * Emitted immediately before command execution.
     */
    commandStart: [
        command: AnyCommand,
        context: CommandContext<ParsedArguments<ArgumentSchema>>,
        route: CommandRoute,
    ];

    /**
     * Emitted after a command completes without throwing.
     */
    commandSuccess: [
        command: AnyCommand,
        context: CommandContext<ParsedArguments<ArgumentSchema>>,
        route: CommandRoute,
    ];

    /**
     * Emitted after a command throws an error.
     */
    commandError: [
        command: AnyCommand,
        error: unknown,
        context: CommandContext<ParsedArguments<ArgumentSchema>>,
        route: CommandRoute,
    ];
}

/**
 * Registers and dispatches unified prefix and slash commands.
 *
 * The manager emits:
 *
 * - `commandStart(command, context, route)` before execution.
 * - `commandSuccess(command, context, route)` after successful execution.
 * - `commandError(command, error, context, route)` after an exception.
 */
export class CommandManager extends EventEmitter {
    /**
     * Canonical routes keyed by normalized paths.
     *
     * Example keys include `ping`, `admin ban`, and `admin user info`.
     */
    public readonly routes: Collection<string, CommandRoute>;

    /**
     * Prefix-command lookup containing canonical paths, alias combinations, and
     * message-default parent paths.
     *
     * The value is the command definition rather than its route. Use
     * {@link routes} when route or group metadata is required.
     */
    public readonly commands: Collection<string, AnyCommand>;

    private readonly registry: CommandRouteRegistry;

    private readonly config: ResolvedCommandHandlerConfig;

    private readonly accessController: CommandAccessController;

    private static _instance: CommandManager | undefined;

    /**
     * Creates a command manager.
     *
     * The most recently constructed manager is also exposed through
     * {@link CommandManager.instance}.
     *
     * @param config - Prefix, access, logging, and feedback configuration.
     */
    public constructor(config: CommandHandlerConfig) {
        super();

        this.config = resolveCommandHandlerConfig(config);

        this.registry = new CommandRouteRegistry();

        this.routes = this.registry.routes;
        this.commands = this.registry.commands;

        this.accessController = new CommandAccessController(this.config);

        if (this.config.help) {
            this.registry.register([
                createGeneratedHelpRoute(this.config.help, {
                    getRoutes: () => [...this.routes.values()],

                    isDeveloper: (userId) =>
                        this.config.devIds.includes(userId),

                    resolvePrefix: (context) => this.resolveHelpPrefix(context),
                }),
            ]);
        }

        CommandManager._instance = this;
    }

    /**
     * Returns the most recently constructed command manager.
     *
     * @throws Error when no manager has been constructed yet.
     */
    public static get instance(): CommandManager {
        if (!CommandManager._instance) {
            throw new Error("CommandManager has not been initialized yet.");
        }

        return CommandManager._instance;
    }

    /**
     * Registers flat commands.
     *
     * This compatibility API maps each command to a single-segment route. Use
     * {@link registerCommandRoutes} for subcommands and command groups.
     *
     * Registration is atomic. No command is added when any command in the
     * supplied batch is invalid or conflicts with an existing path or alias.
     *
     * @param commands - Flat commands to register.
     *
     * @throws Error when a command is invalid or conflicts with an existing
     * command or alias.
     */
    public registerCommands(commands: readonly AnyCommand[]): void {
        this.registerCommandRoutes(
            commands.map((command) => ({
                path: [command.name],
                command,
                groups: [],
            })),
        );
    }

    /**
     * Registers canonical command routes and their prefix aliases.
     *
     * The entire batch is validated before the manager is mutated.
     *
     * @param routes - Routes to register.
     *
     * @throws Error when a route is invalid or when a canonical path or alias
     * conflicts with an existing route.
     */
    public registerCommandRoutes(routes: readonly CommandRoute[]): void {
        this.registry.register(routes);
    }

    /**
     * Handles a Discord message as a possible prefix command.
     *
     * Pass messages from `messageCreate` or `messageUpdate` to this method.
     *
     * The returned value is `true` only when a resolved command completes
     * successfully. Unrelated messages, rejected users, parsing failures,
     * access failures, and command exceptions return `false`.
     *
     * @param message - Discord message to inspect.
     */
    public async handleMessage(message: Message): Promise<boolean> {
        const prefix = await this.resolvePrefix(message);

        const normalizedContent = message.content
            .replace(/[\u200B-\u200D\uFEFF]/gu, "")
            .trimStart();

        if (!normalizedContent.startsWith(prefix)) {
            return false;
        }

        if (
            !this.accessController.canProcessUser(
                message.author.id,
                message.author.bot,
            )
        ) {
            return false;
        }

        const commandInput = normalizedContent.slice(prefix.length).trim();

        const tokenized = tokenizeArguments(commandInput);

        if (!tokenized.success) {
            await this.createContext(message, {}).replyError(
                tokenized.error.message,
            );

            return false;
        }

        const resolved = this.registry.resolveMessage(tokenized.tokens);

        if (!resolved) {
            return false;
        }

        const { route, consumedTokens } = resolved;

        const baseContext = this.createContext(message, {});

        if (!(await this.accessController.checkRoute(route, baseContext))) {
            return false;
        }

        const schema = route.command.arguments ?? EMPTY_ARGUMENTS;

        const parsed = await parseMessageArguments(
            schema,
            message,
            tokenized.tokens.slice(consumedTokens),
        );

        if (!parsed.success) {
            const usage = formatArgumentUsage(schema);

            const usageText = usage
                ? `\nUsage: \`${prefix}${route.path.join(" ")} ${usage}\``
                : "";

            await baseContext.replyError(parsed.error.message + usageText);

            return false;
        }

        return this.executeCommand(
            route,
            this.createContext(message, parsed.value),
        );
    }

    /**
     * Handles supported Discord command interactions.
     *
     * Chat-input interactions execute commands. Autocomplete interactions are
     * routed to the focused argument's autocomplete handler.
     */
    public async handleInteraction(
        interaction: BaseInteraction,
    ): Promise<boolean> {
        if (interaction.isAutocomplete()) {
            return this.handleAutocompleteInteraction(interaction);
        }

        if (!interaction.isChatInputCommand()) {
            return false;
        }

        return this.handleChatInputInteraction(interaction);
    }

    private async handleChatInputInteraction(
        interaction: ChatInputCommandInteraction,
    ): Promise<boolean> {
        if (
            !this.accessController.canProcessUser(
                interaction.user.id,
                interaction.user.bot,
            )
        ) {
            return false;
        }

        const route = this.resolveInteractionRoute(interaction);

        if (!route) {
            return false;
        }

        const baseContext = this.createContext(interaction, {});

        if (!(await this.accessController.checkRoute(route, baseContext))) {
            return false;
        }

        const parsed = await parseInteractionArguments(
            route.command.arguments ?? EMPTY_ARGUMENTS,
            interaction,
        );

        if (!parsed.success) {
            await baseContext.replyError(parsed.error.message);
            return false;
        }

        return this.executeCommand(
            route,
            this.createContext(interaction, parsed.value),
        );
    }

    private async handleAutocompleteInteraction(
        interaction: AutocompleteInteraction,
    ): Promise<boolean> {
        if (
            !this.accessController.canProcessUser(
                interaction.user.id,
                interaction.user.bot,
            )
        ) {
            await interaction.respond([]).catch(() => {});
            return false;
        }

        const route = this.resolveInteractionRoute(interaction);

        if (!route) {
            await interaction.respond([]).catch(() => {});
            return false;
        }

        if (!this.accessController.checkAutocompleteRoute(route, interaction)) {
            await interaction.respond([]).catch(() => {});
            return false;
        }

        try {
            const handled = await respondToArgumentAutocomplete(
                route.command.arguments ?? EMPTY_ARGUMENTS,
                interaction,
            );

            if (!handled) {
                await interaction.respond([]);
            }

            return handled;
        } catch (error) {
            this.config.logger.error(
                `Error autocompleting ${route.path.join(" ")}:`,
                error,
            );

            await interaction.respond([]).catch(() => {});

            return false;
        }
    }

    private resolveInteractionRoute(
        interaction: ChatInputCommandInteraction | AutocompleteInteraction,
    ): CommandRoute | null {
        const subcommandGroup = interaction.options.getSubcommandGroup(false);

        const subcommand = interaction.options.getSubcommand(false);

        const path = [
            interaction.commandName,
            ...(subcommandGroup ? [subcommandGroup] : []),
            ...(subcommand ? [subcommand] : []),
        ];

        const route = this.registry.getCanonical(path);

        return route && isSlashRouteEnabled(route) ? route : null;
    }

    private resolvePrefix(message: Message): Promise<string> {
        const prefix = this.config.prefix;

        return Promise.resolve(
            typeof prefix === "function" ? prefix(message) : prefix,
        );
    }

    private resolveHelpPrefix(
        context: CommandContext<object>,
    ): Promise<string> {
        const prefix = this.config.prefix;

        if (typeof prefix === "string") {
            return Promise.resolve(prefix);
        }

        const message = context.message;

        return message
            ? Promise.resolve(prefix(message))
            : Promise.resolve("<prefix>");
    }

    private createContext<Arguments extends object>(
        payload: ChatInputCommandInteraction | Message,
        args: Arguments,
    ): CommandContext<Arguments> {
        return new CommandContext(payload, args, {
            logger: this.config.logger,
            feedbackRenderer: this.config.feedbackRenderer,
            devIds: this.config.devIds,
        });
    }

    private async executeCommand(
        route: CommandRoute,
        context: CommandContext<ParsedArguments<ArgumentSchema>>,
    ): Promise<boolean> {
        const commandName = route.path.join(" ");

        try {
            this.emit("commandStart", route.command, context, route);

            await route.command.execute(context);

            this.emit("commandSuccess", route.command, context, route);

            return true;
        } catch (error) {
            this.config.logger.error(`Error executing ${commandName}:`, error);

            await context
                .replyError(
                    "An unexpected error occurred while executing this command.",
                )
                .catch(() => {});

            this.emit("commandError", route.command, error, context, route);

            return false;
        }
    }
}

import { Collection } from "discord.js";
import type { AnyCommand, CommandGroup } from "./command";
import { validateCommandRoute } from "./validation";

/**
 * A canonical command path supported by Discord.
 *
 * The tuple represents one of these forms:
 *
 * - `[command]`
 * - `[command, subcommand]`
 * - `[command, subcommandGroup, subcommand]`
 */
export type CommandPath =
    | readonly [string]
    | readonly [string, string]
    | readonly [string, string, string];

/**
 * Associates a command with its canonical path and inherited group metadata.
 */
export interface CommandRoute {
    /**
     * Canonical route segments in root-to-leaf order.
     */
    path: CommandPath;

    /**
     * Command executed when this route is resolved.
     */
    command: AnyCommand;

    /**
     * One metadata entry for every route segment except the command leaf.
     *
     * A flat command has no groups, a direct subcommand has one group, and a
     * grouped subcommand has two groups.
     */
    groups?: readonly CommandGroup[];
}

/**
 * Creates a normalized, case-insensitive lookup key for a command path.
 *
 * @internal
 */
export function createRouteKey(path: readonly string[]): string {
    return path.map((segment) => segment.toLowerCase()).join(" ");
}

function getSegmentAliases(
    route: CommandRoute,
    index: number,
): readonly string[] {
    if (index === route.path.length - 1) {
        return route.command.aliases ?? [];
    }

    return route.groups?.[index]?.aliases ?? [];
}

/**
 * Produces every canonical and aliased lookup key for a route prefix.
 *
 * @internal
 */
export function createRoutePrefixLookupKeys(
    route: CommandRoute,
    segmentCount: number,
): string[] {
    const variants = route.path
        .slice(0, segmentCount)
        .map((segment, index) => [segment, ...getSegmentAliases(route, index)]);

    let keys: string[][] = [[]];

    for (const segmentVariants of variants) {
        keys = keys.flatMap((prefix) =>
            segmentVariants.map((segment) => [...prefix, segment]),
        );
    }

    return [...new Set(keys.map(createRouteKey))];
}

/**
 * Produces every canonical and aliased lookup key for a prefix route.
 *
 * For example, a route whose root and leaf both have one alias produces all
 * four combinations.
 *
 * @internal
 */
export function createRouteLookupKeys(route: CommandRoute): string[] {
    return createRoutePrefixLookupKeys(route, route.path.length);
}

/**
 * Produces every canonical and aliased parent lookup key for a message-default
 * command route.
 *
 * The command leaf and its aliases are intentionally omitted because invoking
 * a message default means that no explicit subcommand segment was supplied.
 *
 * @internal
 */
export function createMessageDefaultLookupKeys(route: CommandRoute): string[] {
    if (!route.command.messageDefault || route.path.length < 2) {
        return [];
    }

    return createRoutePrefixLookupKeys(route, route.path.length - 1);
}

/**
 * Result of matching a prefix-command route.
 *
 * @internal
 */
export interface ResolvedMessageRoute {
    route: CommandRoute;
    consumedTokens: number;
}

/**
 * Stores canonical command routes, prefix-command alias lookups, and
 * message-default parent lookups.
 *
 * Registration is transactional: an invalid or conflicting route prevents the
 * entire batch from being applied.
 *
 * @internal
 */
export class CommandRouteRegistry {
    /**
     * Canonical routes keyed by their normalized path.
     */
    public readonly routes = new Collection<string, CommandRoute>();

    /**
     * Prefix-command lookup containing canonical routes, aliases, and
     * message-default parent paths.
     */
    public readonly commands = new Collection<string, AnyCommand>();

    private readonly routeLookup = new Collection<string, CommandRoute>();

    private readonly messageDefaultLookup = new Collection<
        string,
        CommandRoute
    >();

    /**
     * Registers a collection of routes as one atomic operation.
     *
     * @param routes - Routes to validate and register.
     *
     * @throws Error when a route is invalid or when a path, alias, or
     * message-default parent conflicts with another route.
     */
    public register(routes: readonly CommandRoute[]): void {
        const stagedCanonical = new Map<string, CommandRoute>();
        const stagedLookup = new Map<string, CommandRoute>();
        const stagedMessageDefaults = new Map<string, CommandRoute>();

        for (const route of routes) {
            validateCommandRoute(route);

            const canonicalKey = createRouteKey(route.path);

            if (
                this.routes.has(canonicalKey) ||
                stagedCanonical.has(canonicalKey)
            ) {
                throw new Error(
                    `Command route "${canonicalKey}" is already registered.`,
                );
            }

            stagedCanonical.set(canonicalKey, route);

            for (const lookupKey of createRouteLookupKeys(route)) {
                const existing =
                    stagedLookup.get(lookupKey) ??
                    this.routeLookup.get(lookupKey);

                if (
                    existing &&
                    createRouteKey(existing.path) !== canonicalKey
                ) {
                    throw new Error(
                        `Command route or alias "${lookupKey}" is already ` +
                            `registered by "${existing.path.join(" ")}".`,
                    );
                }

                stagedLookup.set(lookupKey, route);
            }

            for (const lookupKey of createMessageDefaultLookupKeys(route)) {
                const existing =
                    stagedMessageDefaults.get(lookupKey) ??
                    this.messageDefaultLookup.get(lookupKey);

                if (
                    existing &&
                    createRouteKey(existing.path) !== canonicalKey
                ) {
                    throw new Error(
                        `Message-default route "${lookupKey}" is already ` +
                            `registered by "${existing.path.join(" ")}".`,
                    );
                }

                stagedMessageDefaults.set(lookupKey, route);
            }
        }

        /*
         * Prevent a real executable route from occupying a message-default
         * parent path. Without this check, the explicit route would always
         * shadow the default during longest-route resolution.
         */
        for (const [lookupKey, defaultRoute] of stagedMessageDefaults) {
            const explicitRoute =
                stagedLookup.get(lookupKey) ?? this.routeLookup.get(lookupKey);

            if (explicitRoute) {
                throw new Error(
                    `Message-default parent "${lookupKey}" for ` +
                        `"${defaultRoute.path.join(" ")}" conflicts with ` +
                        `the executable route "${explicitRoute.path.join(" ")}".`,
                );
            }
        }

        /*
         * Perform the inverse check for routes registered after an existing
         * message default.
         */
        for (const [lookupKey, explicitRoute] of stagedLookup) {
            const defaultRoute = this.messageDefaultLookup.get(lookupKey);

            if (defaultRoute) {
                throw new Error(
                    `Command route or alias "${lookupKey}" for ` +
                        `"${explicitRoute.path.join(" ")}" conflicts with ` +
                        `the message-default route "${defaultRoute.path.join(" ")}".`,
                );
            }
        }

        for (const [canonicalKey, route] of stagedCanonical) {
            this.routes.set(canonicalKey, route);
        }

        for (const [lookupKey, route] of stagedLookup) {
            this.routeLookup.set(lookupKey, route);
            this.commands.set(lookupKey, route.command);
        }

        for (const [lookupKey, route] of stagedMessageDefaults) {
            this.messageDefaultLookup.set(lookupKey, route);
            this.commands.set(lookupKey, route.command);
        }
    }

    /**
     * Resolves an exact canonical route.
     *
     * Slash interactions use canonical Discord names and therefore do not use
     * the alias or message-default lookups.
     *
     * @param path - Canonical route segments.
     */
    public getCanonical(path: readonly string[]): CommandRoute | null {
        return this.routes.get(createRouteKey(path)) ?? null;
    }

    /**
     * Resolves the longest matching prefix-command route.
     *
     * Explicit canonical and aliased routes are checked before message-default
     * parent routes. This guarantees that an explicitly supplied subcommand
     * always wins over a default subcommand.
     *
     * @param tokens - Tokenized prefix-command input.
     */
    public resolveMessage(
        tokens: readonly string[],
    ): ResolvedMessageRoute | null {
        const maximumRouteLength = Math.min(3, tokens.length);

        for (let length = maximumRouteLength; length >= 1; length--) {
            const route = this.routeLookup.get(
                createRouteKey(tokens.slice(0, length)),
            );

            if (route) {
                return {
                    route,
                    consumedTokens: length,
                };
            }
        }

        const maximumParentLength = Math.min(2, tokens.length);

        for (let length = maximumParentLength; length >= 1; length--) {
            const route = this.messageDefaultLookup.get(
                createRouteKey(tokens.slice(0, length)),
            );

            if (route) {
                return {
                    route,
                    consumedTokens: length,
                };
            }
        }

        return null;
    }
}

import {
	InteractionContextType,
	type PermissionResolvable,
	PermissionsBitField,
	SlashCommandBuilder,
	type SlashCommandSubcommandBuilder,
} from "discord.js";
import { addArgumentsToSlashCommand } from "../arguments";
import { getEffectiveCommandAccess, isSlashRouteEnabled } from "./access";
import { type AnyCommand, type CommandGroup, EMPTY_ARGUMENTS } from "./command";
import { type CommandRoute, createRouteKey } from "./route";
import { validateCommandRoute } from "./validation";

/** JSON payload produced for Discord slash-command registration. */
export type SlashCommandPayload = ReturnType<SlashCommandBuilder["toJSON"]>;

type DirectSubcommandRoute = CommandRoute & {
	path: readonly [string, string];
	groups: readonly [CommandGroup];
};

type GroupedSubcommandRoute = CommandRoute & {
	path: readonly [string, string, string];
	groups: readonly [CommandGroup, CommandGroup];
};

function isDirectSubcommandRoute(
	route: CommandRoute,
): route is DirectSubcommandRoute {
	return route.path.length === 2 && route.groups?.length === 1;
}

function isGroupedSubcommandRoute(
	route: CommandRoute,
): route is GroupedSubcommandRoute {
	return route.path.length === 3 && route.groups?.length === 2;
}

function applyRootCommandSettings(
	builder: SlashCommandBuilder,
	guildOnly: boolean,
	userPermissions: readonly PermissionResolvable[],
): void {
	if (guildOnly) {
		builder.setContexts(InteractionContextType.Guild);
	}

	if (userPermissions.length > 0) {
		builder.setDefaultMemberPermissions(
			new PermissionsBitField(userPermissions).bitfield,
		);
	}
}

function addRouteArguments(
	builder: SlashCommandBuilder | SlashCommandSubcommandBuilder,
	route: CommandRoute,
): void {
	addArgumentsToSlashCommand(
		builder,
		route.command.arguments ?? EMPTY_ARGUMENTS,
	);
}

function createFlatSlashCommandBuilder(
	route: CommandRoute,
): SlashCommandBuilder {
	const builder = new SlashCommandBuilder()
		.setName(route.command.name)
		.setDescription(route.command.description);

	const access = getEffectiveCommandAccess(route);

	applyRootCommandSettings(builder, access.guildOnly, access.userPermissions);

	addRouteArguments(builder, route);

	return builder;
}

function valueSignature(values: readonly unknown[]): string {
	return values.map(String).join("\u0000");
}

function assertConsistentGroupMetadata(
	routes: readonly CommandRoute[],
	groupIndex: number,
): CommandGroup {
	const first = routes[0]?.groups?.[groupIndex];

	if (!first) {
		throw new Error("Missing command group metadata.");
	}

	for (const route of routes.slice(1)) {
		const candidate = route.groups?.[groupIndex];

		if (!candidate) {
			throw new Error(
				`Missing group metadata for route "${route.path.join(" ")}".`,
			);
		}

		if (
			candidate.description !== first.description ||
			candidate.guildOnly !== first.guildOnly ||
			candidate.slash !== first.slash ||
			valueSignature(candidate.userPermissions ?? []) !==
				valueSignature(first.userPermissions ?? [])
		) {
			throw new Error(
				"Inconsistent metadata for command group " +
					`"${route.path.slice(0, groupIndex + 1).join(" ")}".`,
			);
		}
	}

	return first;
}

function createNestedSlashCommandBuilder(
	rootName: string,
	routes: readonly CommandRoute[],
): SlashCommandBuilder {
	const rootGroup = assertConsistentGroupMetadata(routes, 0);

	const builder = new SlashCommandBuilder()
		.setName(rootName)
		.setDescription(rootGroup.description);

	const allGuildOnly = routes.every(
		(route) => getEffectiveCommandAccess(route).guildOnly,
	);

	applyRootCommandSettings(
		builder,
		rootGroup.guildOnly === true || allGuildOnly,
		rootGroup.userPermissions ?? [],
	);

	const directSubcommands = routes
		.filter(isDirectSubcommandRoute)
		.sort((left, right) =>
			createRouteKey(left.path).localeCompare(createRouteKey(right.path)),
		);

	const groupedRoutes = routes.filter(isGroupedSubcommandRoute);

	const groupNames = new Set(groupedRoutes.map((route) => route.path[1]));

	for (const route of directSubcommands) {
		const subcommandName = route.path[1];

		if (groupNames.has(subcommandName)) {
			throw new Error(
				`"${rootName} ${subcommandName}" cannot be both ` +
					"a subcommand and a subcommand group.",
			);
		}
	}

	if (directSubcommands.length + groupNames.size > 25) {
		throw new Error(
			`Slash command "${rootName}" cannot contain more ` +
				"than 25 subcommands and subcommand groups.",
		);
	}

	for (const route of directSubcommands) {
		builder.addSubcommand((subcommand) => {
			subcommand
				.setName(route.path[1])
				.setDescription(route.command.description);

			addRouteArguments(subcommand, route);

			return subcommand;
		});
	}

	const groupedByName = new Map<string, GroupedSubcommandRoute[]>();

	for (const route of groupedRoutes) {
		const groupName = route.path[1];
		const existing = groupedByName.get(groupName) ?? [];

		existing.push(route);
		groupedByName.set(groupName, existing);
	}

	const sortedGroups = [...groupedByName.entries()].sort(([left], [right]) =>
		left.localeCompare(right),
	);

	for (const [groupName, groupRoutes] of sortedGroups) {
		if (groupRoutes.length > 25) {
			throw new Error(
				"Slash subcommand group " +
					`"${rootName} ${groupName}" cannot contain ` +
					"more than 25 subcommands.",
			);
		}

		const group = assertConsistentGroupMetadata(groupRoutes, 1);

		builder.addSubcommandGroup((subcommandGroup) => {
			subcommandGroup.setName(groupName).setDescription(group.description);

			const sortedRoutes = [...groupRoutes].sort((left, right) =>
				createRouteKey(left.path).localeCompare(createRouteKey(right.path)),
			);

			for (const route of sortedRoutes) {
				subcommandGroup.addSubcommand((subcommand) => {
					subcommand
						.setName(route.path[2])
						.setDescription(route.command.description);

					addRouteArguments(subcommand, route);

					return subcommand;
				});
			}

			return subcommandGroup;
		});
	}

	return builder;
}

/**
 * Creates Discord.js slash-command builders from canonical command routes.
 *
 * Routes sharing a root are combined into subcommands and subcommand groups.
 * Prefix-only routes whose effective `slash` setting is `false` are omitted.
 *
 * The returned builders are sorted by root-command name.
 *
 * @param routes - Canonical command routes to convert.
 *
 * @throws Error when the routes form a command structure that Discord cannot
 * represent, such as combining a directly executable root with subcommands.
 */
export function createSlashCommandBuilders(
	routes: readonly CommandRoute[],
): SlashCommandBuilder[] {
	for (const route of routes) {
		validateCommandRoute(route);
	}

	const slashRoutes = routes.filter(isSlashRouteEnabled);

	const routesByRoot = new Map<string, CommandRoute[]>();

	for (const route of slashRoutes) {
		const root = route.path[0];
		const existing = routesByRoot.get(root) ?? [];

		existing.push(route);
		routesByRoot.set(root, existing);
	}

	const builders: SlashCommandBuilder[] = [];

	const sortedRoots = [...routesByRoot.entries()].sort(([left], [right]) =>
		left.localeCompare(right),
	);

	for (const [root, rootRoutes] of sortedRoots) {
		const flatRoutes = rootRoutes.filter((route) => route.path.length === 1);

		const nestedRoutes = rootRoutes.filter((route) => route.path.length > 1);

		if (flatRoutes.length > 0 && nestedRoutes.length > 0) {
			throw new Error(
				`Slash command "${root}" cannot execute directly ` +
					"and also contain subcommands.",
			);
		}

		if (flatRoutes.length > 1) {
			throw new Error(`Duplicate slash command route "${root}".`);
		}

		const flatRoute = flatRoutes[0];

		builders.push(
			flatRoute
				? createFlatSlashCommandBuilder(flatRoute)
				: createNestedSlashCommandBuilder(root, nestedRoutes),
		);
	}

	return builders;
}

/**
 * Creates a Discord.js slash-command builder for one flat command.
 *
 * This compatibility helper does not create subcommands. Use
 * {@link createSlashCommandBuilders} when working with command routes.
 *
 * @param command - Flat command to convert.
 */
export function createSlashCommandBuilder(
	command: AnyCommand,
): SlashCommandBuilder {
	return createFlatSlashCommandBuilder({
		path: [command.name],
		command,
		groups: [],
	});
}

/**
 * Creates JSON-ready slash-command payloads from canonical command routes.
 *
 * This is the registration counterpart to {@link createSlashCommandBuilders}.
 * The returned payloads can be passed directly to `SlashCommandRegistrar`.
 */
export function createSlashCommandPayloads(
	routes: readonly CommandRoute[],
): SlashCommandPayload[] {
	return createSlashCommandBuilders(routes).map((builder) => builder.toJSON());
}

import { validateArgumentSchema } from "../arguments";
import { type AnyCommand, type CommandGroup, EMPTY_ARGUMENTS } from "./command";
import type { CommandRoute } from "./route";

const COMMAND_NAME_PATTERN = /^[a-z0-9_-]{1,32}$/u;

function validateName(name: string, label: string): void {
	if (!COMMAND_NAME_PATTERN.test(name)) {
		throw new Error(
			`${label} "${name}" must contain only lowercase letters, ` +
				"numbers, hyphens, or underscores and must be " +
				"1 to 32 characters long.",
		);
	}
}

function validateDescription(description: string, label: string): void {
	if (description.length < 1 || description.length > 100) {
		throw new Error(
			`${label} must have a description between 1 and 100 characters.`,
		);
	}
}

function validateAliases(aliases: readonly string[], label: string): void {
	for (const alias of aliases) {
		validateName(alias, `${label} alias`);
	}
}

function validateCommand(command: AnyCommand): void {
	validateName(command.name, "Command name");

	validateDescription(command.description, `Command "${command.name}"`);

	validateAliases(command.aliases ?? [], `Command "${command.name}"`);

	validateArgumentSchema(command.name, command.arguments ?? EMPTY_ARGUMENTS);
}

function validateGroup(
	group: CommandGroup,
	groupPath: readonly string[],
): void {
	const label = `Command group "${groupPath.join(" ")}"`;

	validateDescription(group.description, label);
	validateAliases(group.aliases ?? [], label);
}

/**
 * Validates a command route before registration or slash-command generation.
 *
 * Validation covers:
 *
 * - Discord command-name restrictions.
 * - Discord description-length restrictions.
 * - Alias names.
 * - Argument-schema constraints.
 * - Route depth.
 * - Required command-group metadata.
 * - Agreement between the route leaf and command name.
 * - Message-default placement.
 *
 * @param route - Route to validate.
 *
 * @throws Error when the route cannot be safely registered.
 */
export function validateCommandRoute(route: CommandRoute): void {
	const { path, command } = route;
	const groups = route.groups ?? [];

	if (path.length < 1 || path.length > 3) {
		throw new Error(
			`Command route "${path.join(" ")}" must contain 1 to 3 segments.`,
		);
	}

	for (const segment of path) {
		validateName(segment, "Command route segment");
	}

	if (path.at(-1) !== command.name) {
		throw new Error(
			`Command route "${path.join(" ")}" must end with ` +
				`the command name "${command.name}".`,
		);
	}

	if (groups.length !== path.length - 1) {
		throw new Error(
			`Command route "${path.join(" ")}" requires exactly ` +
				`${path.length - 1} group metadata entries.`,
		);
	}

	if (command.messageDefault && path.length === 1) {
		throw new Error(
			`Command route "${path.join(" ")}" cannot be a message default ` +
				"because it has no parent route.",
		);
	}

	validateCommand(command);

	groups.forEach((group, index) => {
		validateGroup(group, path.slice(0, index + 1));
	});
}
